<div class="mb-5 flex flex-wrap gap-2"><?php foreach(['realizado'=>'Fluxo realizado','projetado'=>'Fluxo projetado','dre'=>'DRE simplificado','comparativo'=>'Comparativo mensal'] as $v=>$l):?><a class="btn <?=$type===$v?'btn-primary':'btn-light'?>" href="<?=url('reports')?>&type=<?=$v?>"><?=$l?></a><?php endforeach;?></div>
<form class="card mb-5 flex flex-wrap items-end gap-3 p-4"><input type="hidden" name="route" value="reports"><input type="hidden" name="type" value="<?=e($type)?>"><label><span class="label">Período</span><select class="field" name="period"><option value="current">Mês atual</option><option value="previous" <?=($_GET['period']??'')==='previous'?'selected':''?>>Mês anterior</option><option value="custom" <?=($_GET['period']??'')==='custom'?'selected':''?>>Personalizado</option></select></label><label><span class="label">De</span><input class="field" type="date" name="start" value="<?=e($start)?>"></label><label><span class="label">Até</span><input class="field" type="date" name="end" value="<?=e($end)?>"></label><button class="btn btn-light">Aplicar</button><div class="flex-1"></div><a class="btn btn-light" href="<?=url('reports/export')?>&type=<?=e($type)?>&format=csv&start=<?=e($start)?>&end=<?=e($end)?>"><i data-lucide="sheet"></i>Exportar CSV</a><a class="btn btn-primary" href="<?=url('reports/export')?>&type=<?=e($type)?>&format=pdf&start=<?=e($start)?>&end=<?=e($end)?>"><i data-lucide="file-text"></i>Exportar PDF</a></form>
<div class="card table-wrap"><div class="border-b border-slate-200 p-5 dark:border-slate-800"><h2 class="font-semibold"><?=e($title)?></h2><p class="text-xs text-slate-500"><?=br_date($start)?> a <?=br_date($end)?></p></div><table class="data-table"><thead><tr><?php foreach($columns as $label):?><th><?=e($label)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $value):?><td><?=e($value)?></td><?php endforeach;?></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="<?=count($columns)?>" class="text-center text-slate-500">Sem dados confirmados para este relatório.</td></tr><?php endif;?></tbody></table></div>
